151	  // ─── shared error wrapper ───────────────────────────────────────────────
152	  Future<void> _run(Future<void> Function() fn) async {
153	    setState(() { _busy = true; _error = null; });
154	    try {
155	      await fn();
156	    } on FirebaseAuthException catch (e) {
157	      if (mounted) setState(() => _error = _label(e));
158	    } catch (e) {
159	      if (mounted) setState(() => _error = _generic(e));
160	    } finally {
161	      if (mounted) setState(() => _busy = false);
162	    }
163	  }
164	
165	  static String _label(FirebaseAuthException e) => switch (e.code) {
166	        'invalid-email' => 'That email address is not valid.',
167	        'user-disabled' => 'This account has been disabled.',
168	        'user-not-found' => 'No account found — try creating one.',
169	        'wrong-password' => 'Incorrect password.',
170	        'email-already-in-use' => 'An account already exists for that email.',
171	        'weak-password' => 'Choose a stronger password (8+ characters).',
172	        'invalid-verification-code' => 'That code is incorrect.',
173	        'invalid-phone-number' => 'Enter a valid phone number with the country code.',
174	        'too-many-requests' => 'Too many attempts — please wait a few minutes.',
175	        'network-request-failed' => 'No internet connection.',
176	        _ => e.message ?? 'Something went wrong.',
177	      };
178	
179	  static String _generic(Object e) {
180	    final s = e.toString();
181	    if (s.contains('network') || s.contains('SocketException')) {
182	      return 'No internet connection.';
183	    }
184	    if (s.contains('not configured') || s.contains('PlatformException')) {
185	      return 'Auth service not configured for this environment.';
186	    }
187	    return 'Sign-in failed — please try again.';
188	  }
189	
190	  // ─── Google Sign-In ─────────────────────────────────────────────────────
191	  Future<void> _signInWithGoogle() => _run(() async {
192	        final googleUser = await GoogleSignIn().signIn();
193	        if (googleUser == null) return; // user cancelled
194	        final ga = await googleUser.authentication;
195	        final credential = GoogleAuthProvider.credential(
196	          idToken: ga.idToken,
197	          accessToken: ga.accessToken,
198	        );
199	        await _auth.signInWithCredential(credential);
200	      });
201	
202	  // ─── Email auth ─────────────────────────────────────────────────────────
203	  Future<void> _emailAuth({required bool create}) => _run(() async {
204	        final email = _emailCtrl.text.trim();
205	        final pass = _passwordCtrl.text;
206	        if (email.isEmpty || pass.isEmpty) throw Exception('Please fill in email and password.');
207	        if (create) {
208	          await _auth.createUserWithEmailAndPassword(email: email, password: pass);
209	        } else {
210	          await _auth.signInWithEmailAndPassword(email: email, password: pass);
211	        }
212	      });
213	
214	  // ─── Phone: send OTP ────────────────────────────────────────────────────
215	  Future<void> _sendOtp() => _run(() async {
216	        final raw = _phoneCtrl.text.trim().replaceAll(RegExp(r'\s+'), '');
217	        if (raw.isEmpty) throw Exception('Enter a phone number first.');
218	        final full = '${_country.dialCode}$raw';
219	        await _auth.verifyPhoneNumber(
220	          phoneNumber: full,
221	          forceResendingToken: _resendToken,
222	          verificationCompleted: (cred) => _auth.signInWithCredential(cred),
223	          verificationFailed: (e) {
224	            if (mounted) setState(() => _error = _label(e));
225	          },
226	          codeSent: (id, resend) {
227	            if (mounted) setState(() {
228	              _verificationId = id;
229	              _resendToken = resend;
230	              _codeSent = true;
231	              _error = null;
232	            });
233	          },
234	          codeAutoRetrievalTimeout: (_) {},
235	          timeout: const Duration(seconds: 60),
236	        );
237	      });
238	
239	  // ─── Phone: confirm OTP ──────────────────────────────────────────────────
240	  Future<void> _confirmOtp() => _run(() async {
241	        final id = _verificationId;
242	        final code = _otpCtrl.text.trim();
243	        if (id == null || code.isEmpty) throw Exception('Enter the 6-digit code sent to your phone.');
244	        final cred = PhoneAuthProvider.credential(verificationId: id, smsCode: code);
245	        await _auth.signInWithCredential(cred);
246	      });
247	
248	  // ─── Resend ──────────────────────────────────────────────────────────────
249	  void _resetPhone() => setState(() {
250	        _codeSent = false;
251	        _verificationId = null;
252	        _otpCtrl.clear();
253	        _error = null;
254	      });
