455	class _GoogleGPainter extends CustomPainter {
456	  @override
457	  void paint(Canvas canvas, Size size) {
458	    const colors = [Color(0xFF4285F4), Color(0xFF34A853), Color(0xFFFBBC05), Color(0xFFEA4335)];
459	    final center = Offset(size.width / 2, size.height / 2);
460	    final r = size.width / 2;
461	    final sweep = (2 * 3.14159265) / 4;
462	    final paint = Paint()..style = PaintingStyle.stroke..strokeWidth = size.width * 0.28;
463	    for (int i = 0; i < 4; i++) {
464	      paint.color = colors[i];
465	      canvas.drawArc(Rect.fromCircle(center: center, radius: r * 0.7),
466	          -3.14159265 / 2 + i * sweep, sweep - 0.08, false, paint);
467	    }
468	    // horizontal bar
469	    paint
470	      ..color = Color(0xFF4285F4)
471	      ..strokeWidth = size.width * 0.28;
472	    canvas.drawLine(
473	      Offset(center.dx, center.dy),
474	      Offset(size.width, center.dy),
475	      paint,
476	    );
477	  }
478	
479	  @override
480	  bool shouldRepaint(covariant CustomPainter old) => false;
481	}
