import 'package:flutter/material.dart';

/// Design tokens. Every colour, gap, radius and shadow in the app resolves through here.
abstract final class Tokens {
  /// Primary brand seed — dusty rose pink. Material 3 derives the full tonal palette.
  static const seed = Color(0xFFD4748C);

  // Secondary accent — warm terracotta tan
  static const secondarySeed = Color(0xFFC49A72);
  // Tertiary — soft blush
  static const tertiarySeed = Color(0xFFE8A0B0);

  // Tan surface palette for direct use
  static const tanBase = Color(0xFFF5E6D3);
  static const tanDark = Color(0xFFEDD5B8);
  static const pinkAccent = Color(0xFFD4748C);
  static const pinkLight = Color(0xFFF2B8C6);

  // Radii scale
  static const radiusXs = 4.0;
  static const radiusSm = 8.0;
  static const radiusMd = 16.0;
  static const radiusLg = 24.0;
  static const radiusXl = 32.0;
  static const radiusPill = 999.0;

  // 4pt spacing scale
  static const spaceXs = 4.0;
  static const spaceSm = 8.0;
  static const spaceMd = 16.0;
  static const spaceLg = 24.0;
  static const spaceXl = 32.0;
  static const space2Xl = 48.0;

  // Match card layout ratio
  static const cardAspect = 1 / 1.35;

  // Elevation & Shadows
  static const shadowLevel1 = [
    BoxShadow(
      color: Color(0x0F000000),
      blurRadius: 8,
      offset: Offset(0, 2),
    ),
  ];

  static const shadowLevel2 = [
    BoxShadow(
      color: Color(0x1A000000),
      blurRadius: 16,
      offset: Offset(0, 4),
    ),
  ];

  static const shadowLevel3 = [
    BoxShadow(
      color: Color(0x26000000),
      blurRadius: 24,
      offset: Offset(0, 8),
    ),
  ];
}

import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import 'tokens.dart';

/// Central Material 3 adaptive theme generator.
abstract final class AppTheme {
  static ThemeData light() => _build(Brightness.light);
  static ThemeData dark() => _build(Brightness.dark);

  static ThemeData _build(Brightness brightness) {
    final scheme = ColorScheme.fromSeed(
      seedColor: Tokens.seed,
      brightness: brightness,
      dynamicSchemeVariant: DynamicSchemeVariant.tonalSpot,
    );

    final base = ThemeData(
      colorScheme: scheme,
      useMaterial3: true,
      brightness: brightness,
    );

    final textTheme = GoogleFonts.interTextTheme(base.textTheme).copyWith(
      headlineLarge: GoogleFonts.outfit(
        textStyle: base.textTheme.headlineLarge?.copyWith(fontWeight: FontWeight.w700),
      ),
      headlineMedium: GoogleFonts.outfit(
        textStyle: base.textTheme.headlineMedium?.copyWith(fontWeight: FontWeight.w600),
      ),
      titleLarge: GoogleFonts.outfit(
        textStyle: base.textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w600),
      ),
    );

    return base.copyWith(
      scaffoldBackgroundColor: brightness == Brightness.light
          ? Tokens.tanBase   // warm tan for light mode
          : scheme.surface,
      textTheme: textTheme,
      cardTheme: CardThemeData(
        elevation: 0,
        color: scheme.surfaceContainerLow,
        margin: EdgeInsets.zero,
        clipBehavior: Clip.antiAlias,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.all(Radius.circular(Tokens.radiusMd)),
        ),
      ),
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          minimumSize: const Size.fromHeight(52),
          elevation: 0,
          shape: const RoundedRectangleBorder(
            borderRadius: BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          ),
          textStyle: textTheme.titleSmall?.copyWith(fontWeight: FontWeight.w600),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          minimumSize: const Size.fromHeight(52),
          shape: const RoundedRectangleBorder(
            borderRadius: BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          ),
          side: BorderSide(color: scheme.outlineVariant),
          textStyle: textTheme.titleSmall?.copyWith(fontWeight: FontWeight.w600),
        ),
      ),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: scheme.surfaceContainerHighest.withValues(alpha: 0.4),
        contentPadding: const EdgeInsets.symmetric(
          horizontal: Tokens.spaceMd,
          vertical: Tokens.spaceMd,
        ),
        border: const OutlineInputBorder(
          borderRadius: BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          borderSide: BorderSide.none,
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          borderSide: BorderSide(color: scheme.outlineVariant.withValues(alpha: 0.5)),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          borderSide: BorderSide(color: scheme.primary, width: 2),
        ),
        errorBorder: OutlineInputBorder(
          borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          borderSide: BorderSide(color: scheme.error),
        ),
      ),
      chipTheme: base.chipTheme.copyWith(
        shape: const StadiumBorder(),
        side: BorderSide.none,
        backgroundColor: scheme.surfaceContainerHigh,
      ),
      appBarTheme: AppBarTheme(
        backgroundColor: scheme.surface,
        scrolledUnderElevation: 1.0,
        centerTitle: false,
        elevation: 0,
        titleTextStyle: textTheme.titleLarge?.copyWith(
          color: scheme.onSurface,
        ),
      ),
      navigationBarTheme: NavigationBarThemeData(
        elevation: 2.0,
        indicatorColor: scheme.primaryContainer,
        backgroundColor: scheme.surfaceContainerLow,
        labelTextStyle: WidgetStateProperty.resolveWith((states) {
          if (states.contains(WidgetState.selected)) {
            return textTheme.labelSmall?.copyWith(
              fontWeight: FontWeight.w600,
              color: scheme.onSurface,
            );
          }
          return textTheme.labelSmall?.copyWith(
            color: scheme.onSurfaceVariant,
          );
        }),
      ),
      bottomSheetTheme: BottomSheetThemeData(
        backgroundColor: scheme.surfaceContainerLowest,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(Tokens.radiusLg)),
        ),
        showDragHandle: true,
      ),
      dialogTheme: DialogThemeData(
        backgroundColor: scheme.surfaceContainerHigh,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.all(Radius.circular(Tokens.radiusLg)),
        ),
      ),
    );
  }
}

