11	/// Multi-breakpoint responsive builder adapting dynamically to Mobile, Tablet, and Desktop layouts.
12	class ResponsiveLayout extends StatelessWidget {
13	  const ResponsiveLayout({
14	    super.key,
15	    required this.mobile,
16	    this.tablet,
17	    this.desktop,
18	  });
19	
20	  final ResponsiveWidgetBuilder mobile;
21	  final ResponsiveWidgetBuilder? tablet;
22	  final ResponsiveWidgetBuilder? desktop;
23	
24	  @override
25	  Widget build(BuildContext context) {
26	    return LayoutBuilder(
27	      builder: (context, constraints) {
28	        final screenType = Breakpoints.fromWidth(constraints.maxWidth);
29	
30	        if (screenType == ScreenType.desktop || screenType == ScreenType.ultraWide) {
31	          if (desktop != null) return desktop!(context, constraints);
32	          if (tablet != null) return tablet!(context, constraints);
33	          return mobile(context, constraints);
34	        }
35	
36	        if (screenType == ScreenType.tablet) {
37	          if (tablet != null) return tablet!(context, constraints);
38	          return mobile(context, constraints);
39	        }
40	
41	        return mobile(context, constraints);
42	      },
43	    );
44	  }
45	}
46	
47	/// Adaptive container that centers content and enforces max readability constraints
48	/// across larger screens, eliminating horizontal overflow.
49	class AdaptiveContainer extends StatelessWidget {
50	  const AdaptiveContainer({
51	    super.key,
52	    required this.child,
53	    this.maxWidth,
54	    this.padding,
55	    this.alignment = Alignment.topCenter,
56	  });
57	
58	  final Widget child;
59	  final double? maxWidth;
60	  final EdgeInsetsGeometry? padding;
61	  final AlignmentGeometry alignment;
62	
63	  @override
64	  Widget build(BuildContext context) {
65	    return LayoutBuilder(
66	      builder: (context, constraints) {
67	        final screenType = Breakpoints.fromWidth(constraints.maxWidth);
68	        final defaultMaxWidth = switch (screenType) {
69	          ScreenType.mobile => double.infinity,
70	          ScreenType.tablet => Breakpoints.maxContentWidthTablet,
71	          ScreenType.desktop => Breakpoints.maxContentWidthDesktop,
72	          ScreenType.ultraWide => Breakpoints.maxContentWidthDesktop,
73	        };
74	
75	        final effectiveMaxWidth = maxWidth ?? defaultMaxWidth;
76	        final horizontalMargin = Breakpoints.marginOf(context);
77	
78	        return Align(
79	          alignment: alignment,
80	          child: ConstrainedBox(
81	            constraints: BoxConstraints(
82	              maxWidth: effectiveMaxWidth,
83	            ),
84	            child: Padding(
85	              padding: padding ?? EdgeInsets.symmetric(horizontal: horizontalMargin),
86	              child: child,
87	            ),
88	          ),
89	        );
90	      },
91	    );
