import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:geolocator/geolocator.dart';

import '../../core/models.dart';
import '../../core/providers.dart';
import '../../core/theme.dart';
import '../../core/widgets.dart';

/// Profile creation. Interest and language selection is a fixed tag set from the
/// backend — no free-text entry, which is what keeps overlap scoring computable.
class ProfileFormScreen extends ConsumerStatefulWidget {
  const ProfileFormScreen({super.key, required this.onNext});

  final VoidCallback onNext;

  @override
  ConsumerState<ProfileFormScreen> createState() => _ProfileFormScreenState();
}

class _ProfileFormScreenState extends ConsumerState<ProfileFormScreen> {
  final _form = GlobalKey<FormState>();
  final _name = TextEditingController();
  final _bio = TextEditingController();
  final _education = TextEditingController();
  final _profession = TextEditingController();
  final _location = TextEditingController();

  DateTime? _dob;
  String? _gender;
  String? _marital;
  Position? _position;
  final _interests = <int>{};
  final _languages = <int>{};
  bool _busy = false;
  String? _error;

  @override
  void dispose() {
    _name.dispose();
    _bio.dispose();
    _education.dispose();
    _profession.dispose();
    _location.dispose();
    super.dispose();
  }

  /// yyyy-MM-dd. The server parses this into a date, and its trigger is what
  /// actually enforces the age floor.
  String? get _dobIso {
    final dob = _dob;
    if (dob == null) return null;
    final m = dob.month.toString().padLeft(2, '0');
    final d = dob.day.toString().padLeft(2, '0');
    return '${dob.year}-$m-$d';
  }

  Future<void> _pickDob() async {
    final now = DateTime.now();
    // The picker simply cannot reach an under-18 date, so the client-side age
    // gate from spec 1.2 is structural rather than a validation message.
    final latestAllowed = DateTime(now.year - 18, now.month, now.day);
    final picked = await showDatePicker(
      context: context,
      initialDate: DateTime(now.year - 25, now.month, now.day),
      firstDate: DateTime(now.year - 100),
      lastDate: latestAllowed,
      helpText: 'Your date of birth',
    );
    if (picked != null) setState(() => _dob = picked);
  }

  /// Coordinates are optional: the feed shows profiles it cannot measure rather
  /// than emptying itself, so a denied permission degrades instead of blocking.
  Future<void> _useCurrentLocation() async {
    setState(() => _error = null);
    try {
      if (!await Geolocator.isLocationServiceEnabled()) {
        setState(() => _error = 'Turn on location services to use distance filters.');
        return;
      }
      var permission = await Geolocator.checkPermission();
      if (permission == LocationPermission.denied) {
        permission = await Geolocator.requestPermission();
      }
      if (permission == LocationPermission.denied || permission == LocationPermission.deniedForever) {
        setState(() => _error = 'Location permission denied. You can still set your city manually.');
        return;
      }
      final position = await Geolocator.getCurrentPosition();
      if (mounted) setState(() => _position = position);
    } catch (_) {
      if (mounted) setState(() => _error = 'Could not read your location.');
    }
  }

  Future<void> _save() async {
    if (!_form.currentState!.validate()) return;
    if (_dob == null) {
      setState(() => _error = 'Please choose your date of birth.');
      return;
    }
    if (_interests.isEmpty) {
      setState(() => _error = 'Pick at least one interest so we can match you well.');
      return;
    }

    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      await ref.read(myProfileProvider.notifier).save({
        'name': _name.text.trim(),
        'gender': _gender,
        'dob': _dobIso,
        'location': _location.text.trim(),
        if (_position != null) 'lat': _position!.latitude,
        if (_position != null) 'lng': _position!.longitude,
        'bio': _bio.text.trim(),
        'education': _education.text.trim(),
        'profession': _profession.text.trim(),
        if (_marital != null) 'maritalStatus': _marital,
        'interestIds': _interests.toList(),
        'languageIds': _languages.toList(),
      });
      if (mounted) widget.onNext();
    } catch (e) {
      if (mounted) setState(() => _error = messageFor(e));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final tags = ref.watch(tagsProvider);

    return Scaffold(
      appBar: AppBar(title: const Text('Your profile')),
      body: AsyncView(
        value: tags,
        onRetry: () => ref.invalidate(tagsProvider),
        builder: (data) => Form(
          key: _form,
          child: ListView(
            padding: const EdgeInsets.all(Tokens.spaceMd),
            children: [
              TextFormField(
                controller: _name,
                textCapitalization: TextCapitalization.words,
                decoration: const InputDecoration(labelText: 'Name'),
                validator: (v) => (v == null || v.trim().isEmpty) ? 'Please enter your name.' : null,
              ),
              const SizedBox(height: Tokens.spaceMd),

              _DobField(dob: _dob, onTap: _pickDob),
              const SizedBox(height: Tokens.spaceMd),

              DropdownButtonFormField<String>(
                initialValue: _gender,
                decoration: const InputDecoration(labelText: 'Gender'),
                items: const [
                  DropdownMenuItem(value: 'male', child: Text('Male')),
                  DropdownMenuItem(value: 'female', child: Text('Female')),
                  DropdownMenuItem(value: 'other', child: Text('Other')),
                ],
                onChanged: (v) => setState(() => _gender = v),
                validator: (v) => v == null ? 'Please select your gender.' : null,
              ),
              const SizedBox(height: Tokens.spaceMd),

              TextFormField(
                controller: _location,
                textCapitalization: TextCapitalization.words,
                decoration: const InputDecoration(labelText: 'City', hintText: 'Lahore'),
              ),
              const SizedBox(height: Tokens.spaceSm),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: _useCurrentLocation,
                      icon: Icon(_position == null ? Icons.my_location : Icons.check_circle_outline),
                      label: Text(_position == null ? 'Use my location' : 'Location set'),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: Tokens.spaceMd),

              DropdownButtonFormField<String>(
                initialValue: _marital,
                decoration: const InputDecoration(labelText: 'Marital status'),
                items: const [
                  DropdownMenuItem(value: 'never_married', child: Text('Never married')),
                  DropdownMenuItem(value: 'divorced', child: Text('Divorced')),
                  DropdownMenuItem(value: 'widowed', child: Text('Widowed')),
                ],
                onChanged: (v) => setState(() => _marital = v),
              ),
              const SizedBox(height: Tokens.spaceMd),

              TextFormField(
                controller: _bio,
                maxLines: 4,
                maxLength: 1000,
                decoration: const InputDecoration(labelText: 'About you', alignLabelWithHint: true),
              ),
              const SizedBox(height: Tokens.spaceSm),

              TextFormField(
                controller: _education,
                decoration: const InputDecoration(labelText: 'Education (optional)'),
              ),
              const SizedBox(height: Tokens.spaceMd),

              TextFormField(
                controller: _profession,
                decoration: const InputDecoration(labelText: 'Profession (optional)'),
              ),
              const SizedBox(height: Tokens.spaceLg),

              const SectionHeader('Interests'),
              _TagPicker(
                tags: data.interests,
                selected: _interests,
                onToggle: (id, on) => setState(() => on ? _interests.add(id) : _interests.remove(id)),
              ),
              const SizedBox(height: Tokens.spaceLg),

              const SectionHeader('Languages'),
              _TagPicker(
                tags: data.languages,
                selected: _languages,
                onToggle: (id, on) => setState(() => on ? _languages.add(id) : _languages.remove(id)),
              ),
              const SizedBox(height: Tokens.spaceXl),

              if (_error != null) ...[
                Semantics(
                  liveRegion: true,
                  child: Text(
                    _error!,
                    style: TextStyle(color: Theme.of(context).colorScheme.error),
                  ),
                ),
                const SizedBox(height: Tokens.spaceMd),
              ],

              FilledButton(
                onPressed: _busy ? null : _save,
                child: Text(_busy ? 'Saving…' : 'Continue'),
              ),
              const SizedBox(height: Tokens.spaceLg),
            ],
          ),
        ),
      ),
    );
  }
}

class _DobField extends StatelessWidget {
  const _DobField({required this.dob, required this.onTap});

  final DateTime? dob;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) => Semantics(
        button: true,
        label: dob == null
            ? 'Date of birth, not set'
            : 'Date of birth ${dob!.day}/${dob!.month}/${dob!.year}',
        child: InkWell(
          onTap: onTap,
          borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          child: InputDecorator(
            decoration: const InputDecoration(
              labelText: 'Date of birth',
              suffixIcon: Icon(Icons.calendar_today_outlined),
            ),
            child: Text(
              dob == null
                  ? 'Select your date of birth'
                  : '${dob!.day}/${dob!.month}/${dob!.year}',
            ),
          ),
        ),
      );
}

class _TagPicker extends StatelessWidget {
  const _TagPicker({required this.tags, required this.selected, required this.onToggle});

  final List<Tag> tags;
  final Set<int> selected;
  final void Function(int id, bool on) onToggle;

  @override
  Widget build(BuildContext context) => Wrap(
        spacing: Tokens.spaceSm,
        runSpacing: Tokens.spaceSm,
        children: [
          for (final tag in tags)
            FilterChip(
              label: Text(tag.label),
              selected: selected.contains(tag.id),
              // selected/focused are announced automatically once the chip has a
              // label, so no extra Semantics wrapper is needed here.
              onSelected: (on) => onToggle(tag.id, on),
            ),
        ],
      );
}

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:image_picker/image_picker.dart';

import '../../core/providers.dart';
import '../../core/storage.dart';
import '../../core/theme.dart';
import '../../core/widgets.dart';

/// Photo step. Spec 1.2: minimum one photo, three to six recommended.
class PhotosScreen extends ConsumerStatefulWidget {
  const PhotosScreen({super.key, required this.onNext});

  final VoidCallback onNext;

  @override
  ConsumerState<PhotosScreen> createState() => _PhotosScreenState();
}

class _PhotosScreenState extends ConsumerState<PhotosScreen> {
  bool _busy = false;
  String? _error;

  Future<void> _add({required bool primary}) async {
    final picked = await ImagePicker().pickImage(
      source: ImageSource.gallery,
      maxWidth: 1600,
      maxHeight: 1600,
      imageQuality: 85,
    );
    if (picked == null) return;

    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      final profile = ref.read(myProfileProvider).valueOrNull;
      final url = await Storage.upload(
        Storage.pathFor(profile?.userId ?? 'unknown', 'profiles'),
        File(picked.path),
      );
      await ref.read(myProfileProvider.notifier).addPhoto(url, makePrimary: primary);
      // The server re-opens verification when the primary photo changes, so the
      // caller must re-check status rather than assume the old verdict stands.
      ref.invalidate(verificationProvider);
    } catch (e) {
      if (mounted) setState(() => _error = messageFor(e));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final profile = ref.watch(myProfileProvider);

    return Scaffold(
      appBar: AppBar(title: const Text('Your photos')),
      body: AsyncView(
        value: profile,
        onRetry: () => ref.invalidate(myProfileProvider),
        builder: (data) {
          final photos = data.photos;
          final enough = photos.isNotEmpty;

          return ListView(
            padding: const EdgeInsets.all(Tokens.spaceMd),
            children: [
              Text(
                enough
                    ? 'Add a few more so people get a sense of you.'
                    : 'Add at least one photo to continue.',
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              const SizedBox(height: Tokens.spaceMd),

              GridView.count(
                crossAxisCount: 3,
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                mainAxisSpacing: Tokens.spaceSm,
                crossAxisSpacing: Tokens.spaceSm,
                children: [
                  for (var i = 0; i < photos.length; i++)
                    _PhotoTile(
                      url: photos[i],
                      isPrimary: i == 0,
                      label: i == 0 ? 'Primary photo' : 'Photo ${i + 1}',
                    ),
                  if (photos.length < 6)
                    _AddTile(
                      busy: _busy,
                      label: photos.isEmpty ? 'Add photo' : 'Add another',
                      onTap: () => _add(primary: photos.isEmpty),
                    ),
                ],
              ),

              const SizedBox(height: Tokens.spaceLg),
              if (!enough && photos.isNotEmpty)
                const Text('Something went wrong saving that photo.'),

              if (_error != null) ...[
                Semantics(
                  liveRegion: true,
                  child: Text(_error!, style: TextStyle(color: Theme.of(context).colorScheme.error)),
                ),
                const SizedBox(height: Tokens.spaceMd),
              ],

              FilledButton(
                onPressed: enough && !_busy ? widget.onNext : null,
                child: const Text('Continue'),
              ),
              const SizedBox(height: Tokens.spaceLg),
            ],
          );
        },
      ),
    );
  }
}

class _PhotoTile extends StatelessWidget {
  const _PhotoTile({required this.url, required this.isPrimary, required this.label});

  final String url;
  final bool isPrimary;
  final String label;

  @override
  Widget build(BuildContext context) => Stack(
        fit: StackFit.expand,
        children: [
          ClipRRect(
            borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusSm)),
            child: ProfilePhoto(url: url, label: label),
          ),
          if (isPrimary)
            Positioned(
              left: 4,
              top: 4,
              child: Semantics(
                label: 'This is your primary photo',
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                  decoration: BoxDecoration(
                    color: Theme.of(context).colorScheme.primary,
                    borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusSm)),
                  ),
                  child: Text(
                    'Main',
                    style: TextStyle(
                      fontSize: 10,
                      color: Theme.of(context).colorScheme.onPrimary,
                    ),
                  ),
                ),
              ),
            ),
        ],
      );
}

class _AddTile extends StatelessWidget {
  const _AddTile({required this.busy, required this.label, required this.onTap});

  final bool busy;
  final String label;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) => Semantics(
        button: true,
        label: label,
        child: InkWell(
          onTap: busy ? null : onTap,
          borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusSm)),
          child: DecoratedBox(
            decoration: BoxDecoration(
              borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusSm)),
              border: Border.all(color: Theme.of(context).colorScheme.outlineVariant),
            ),
            child: Center(
              child: busy
                  ? const SizedBox.square(dimension: 20, child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.add_a_photo_outlined),
            ),
          ),
        ),
      );
}

