/// Wraps a Future in the busy/error lifecycle every onboarding step repeats.
/// Screen state merges `with FormProgress` and calls `_progress(fn)`.
mixin FormProgress<T extends StatefulWidget> on State<T> {
  bool _busy = false;
  String? _error;
  bool get busy => _busy;
  String? get error => _error;

  Future<void> _progress(Future<void> Function() fn) async {
    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      await fn();
    } catch (e) {
      if (mounted) setState(() => _error = messageFor(e));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }
}

