            children: [
              Semantics(
                label: label,
                child: Text(label, textAlign: TextAlign.center, style: Theme.of(context).textTheme.bodyLarge),
              ),
              if (onRetry != null) ...[
                const SizedBox(height: Tokens.spaceMd),
                TextButton(onPressed: onRetry, child: const Text('Try again')),
              ],
            ],
          ),
        ),
      );
}

